'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var minstd = require( '@stdlib/random/base/minstd' ).factory;
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var dkmeansInitPlusPlus = require( './../lib' );


// FIXTURES //

var ROW_MAJOR_DATA = require( './fixtures/row_major.json' );
var COLUMN_MAJOR_DATA = require( './fixtures/column_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dkmeansInitPlusPlus, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 15', function test( t ) {
	t.strictEqual( dkmeansInitPlusPlus.length, 15, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var data;
	var opts;
	var i;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( value, data.M, data.N, data.k, data.trials, data.metric, new Float64Array( data.X ), data.LDX, new Float64Array( data.out ), data.LDO, new Float64Array( data.W1 ), data.strideW1, new Int32Array( data.W2 ), data.strideW2, opts );
		};
	}
});

tape( 'the function throws an error if `k` is greater than `M`', function test( t ) {
	var data;
	var opts;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};

	t.throws( badValue, RangeError, 'throws an error' );
	t.end();

	function badValue() {
		dkmeansInitPlusPlus( data.order, 1, data.N, data.k, data.trials, data.metric, new Float64Array( data.X ), data.LDX, new Float64Array( data.out ), data.LDO, new Float64Array( data.W1 ), data.strideW1, new Int32Array( data.W2 ), data.strideW2, opts );
	}
});

tape( 'the function throws an error when trials is less than or equal to zero', function test( t ) {
	var data;
	var opts;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};

	t.throws( badValue( 0 ), RangeError, 'throws an error when provided ' + 0 );
	t.throws( badValue( -1 ), RangeError, 'throws an error when provided ' + -1 );
	t.end();

	function badValue( value ) {
		return function badValue() {
			dkmeansInitPlusPlus( data.order, data.M, data.N, data.k, value, data.metric, new Float64Array( data.X ), data.LDX, new Float64Array( data.out ), data.LDO, new Float64Array( data.W1 ), data.strideW1, new Int32Array( data.W2 ), data.strideW2, opts );
		};
	}
});

