tape( 'the function returns the output array when k is less than one', function test( t ) {
	var expected;
	var data;
	var opts;
	var out;
	var i;

	data = ROW_MAJOR_DATA;
	opts = {
		'prng': minstd({
			'seed': data.seed
		})
	};
	out = dkmeansInitPlusPlus( data.order, data.M, data.N, 0, data.trials, data.metric, new Float64Array( data.X ), data.LDX, new Float64Array( data.out ), data.LDO, new Float64Array( data.W1 ), data.strideW1, new Int32Array( data.W2 ), data.strideW2, opts );

	expected = new Float64Array( data.out );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isAlmostSameValue( out[ i ], expected[ i ], 0 ), true, 'returns expected value' );
	}
	t.end();
});

